pragma solidity ^0.8.0;

contract GuruVeto {
    address public founder;
    mapping(uint256 => bool) public vetoedProposals;

    constructor() {
        founder = msg.sender;
    }

    function vetoProposal(uint256 proposalId) external {
        require(msg.sender == founder, "Only the founder can veto proposals.");
        vetoedProposals[proposalId] = true;
        // Proposal is now permanently voided.
    }

    function getVetoStatus(uint256 proposalId) public view returns (bool) {
        return vetoedProposals[proposalId];
    }

    function hasBeenVetoed(uint256 proposalId) public view returns (bool) {
        return vetoedProposals[proposalId];
    }
}
